7		Kind     string   // "user", "service", "external"
8		Roles    []string
9		Disabled bool
10	}
11	
12	// Resource is a protected object with a scope path.
13	type Resource struct {
14		ID    string
15		Scope string // e.g. "org/payments/ledger"
16	}
17	
18	// Decision explains one access evaluation.
19	type Decision struct {
20		Allowed bool
21		Reason  string
22		Matched []string
23	}
