476		if len(res.Series) != 0 {
477			t.Fatalf("query before any write = %+v, want empty", res.Series)
478		}
479	
480		mustOK(t, store, `[{"name":"m","timestamp":10,"value":2}]`)
481		mustOK(t, store, `[{"name":"m","timestamp":20,"value":4}]`)
482		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
483		if len(res.Series) != 1 || res.Series[0].Count != 2 || res.Series[0].Average != 3 {
484			t.Fatalf("query after writes = %+v", res.Series)
485		}
486	
487		// 失败批次整批回滚，其中任何点都不能参与后续查询。
488		mustFail(t, store, `[{"name":"m","timestamp":30,"value":8},{"name":"m","timestamp":10,"value":100}]`)
489		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
490		if res.Series[0].Count != 2 || res.Series[0].Average != 3 {
491			t.Fatalf("rolled-back points must not be queryable, got %+v", res.Series)
492		}
493	
494		// 重复点只计一次。
495		mustOK(t, store, `[{"name":"m","timestamp":20,"value":4.0}]`)
